mapper.select:
SELECT a.week_day AS weekDay, a.section, c.name AS courseName, t.name AS teacherName, a.classroom FROM course_selection cs JOIN course_arrange a ON a.course_id = cs.course_id JOIN course c ON c.course_id = cs.course_id LEFT JOIN teacher t ON t.tid = a.tid WHERE cs.sid = #{sid}
AND (cs.semester_id = #{semesterId} OR cs.semester_id IS NULL) AND (a.semester_id = #{semesterId} OR a.semester_id IS NULL)
ORDER BY a.week_day, a.section
